public class Grades {
    static String band(int score) {
        if (score < 0 || score > 100) {
            return "invalid";                    // explicit invalid branch.
        } else if (score >= 90) {
            return "A";                          // 90..100
        } else if (score >= 80) {
            return "B";                          // 80..89
        } else {
            return "C";                          // 0..79
        }
    }

    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }

    static String kind(Day d) {
        return switch (d) {                     // switch expression: must cover all.
            case SAT, SUN -> "weekend";
            case MON, TUE, WED, THU, FRI -> "weekday";
        };
    }

    public static void main(String[] args) {
        System.out.println(band(90) + band(89) + band(100) + band(101));  // ABAinvalid
        System.out.println(kind(Day.FRI));                                // weekday
    }
}
